-- Exile's Reach: phase_area and phase conditions checked against the retail sniff (12.0.1.66709, Alliance human mage).
-- Generated by stage 5 (er_stage5_rules.py); every rule below explains all phase shifts of the sniff (snapshots taken while the
-- player was on a vehicle/taxi are not counted). Phases used only by Horde / other classes are left as they are.

DELETE FROM `phase_area` WHERE `PhaseId` IN (13328,13393,13758,13809,13831,13832,13835,13846,13878,14353,14355,14987,15011,15017,15276,15279,15356,15473,16752) AND `AreaId` IN (10424,10452,10453,10503,10527,10528,10529,10568,10588,10639,11011,13377);

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 26 AND `SourceGroup` IN (13328,13393,13758,13809,13831,13832,13835,13846,13878,14353,14355,14987,15011,15017,15276,15279,15356,15473,16752) AND `SourceEntry` IN (0,10424,10452,10453,10503,10527,10528,10529,10568,10588,10639,11011,13377);

-- Catapults appear in the sniff exactly when phase 13840 is added (13839 is never active for them).
UPDATE `gameobject` SET `PhaseId` = 13840 WHERE `guid` IN (90010001, 90010002, 90010003, 90010004) AND `id` = 326651;
